# Kaggle script kernel (GPU): 32-bit indexing boundary, release and nightly.
import base64, subprocess, sys
open("int32_indexing_boundary.py", "wb").write(base64.b64decode(""))
for spec in [["--upgrade", "torch==2.14.0"], ["--pre", "--upgrade", "torch", "--index-url", "https://download.pytorch.org/whl/nightly/cu130"]]:
    subprocess.run(["pip", "-q", "install", *spec])
    subprocess.run([sys.executable, "int32_indexing_boundary.py"])
print("JOB DONE", flush=True)
